package com.careerpilot.modules.jobmatch.controller;import com.careerpilot.modules.jobmatch.dto.*;import com.careerpilot.modules.jobmatch.mapper.JobMatchMapper;import com.careerpilot.modules.jobmatch.service.JobMatchService;import com.careerpilot.security.CurrentUser;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/job-matches") public class JobMatchController{private final JobMatchService service;public JobMatchController(JobMatchService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED)@Operation(summary="Create a deterministic resume-to-job match",description=JobMatchMapper.DISCLAIMER)public JobMatchResponse create(@Valid@RequestBody CreateJobMatchRequest request){return service.create(CurrentUser.require(),request);}@GetMapping@Operation(summary="List the current student's job-match history")public List<JobMatchSummaryResponse>history(){return service.history(CurrentUser.require());}@GetMapping("/latest")public JobMatchSummaryResponse latest(){return service.latest(CurrentUser.require());}@GetMapping("/{matchId}")@Operation(summary="Get an owned historical job match",description=JobMatchMapper.DISCLAIMER)public JobMatchResponse get(@PathVariable UUID matchId){return service.get(CurrentUser.require(),matchId);}}
